from fastapi.testclient import TestClient
from pydantic import Json
from typing import Annotated
import pytest

app = FastAPI()

@app.post("/upload")
def upload(
    file: Annotated[str, Form()], # Just using str for file to simplify, though usually UploadFile
    tags: Annotated[Json[list[str]], Form()]
):
    return {"file": file, "tags": tags}

client = TestClient(app)

def test_json_list_form():
    # Client sends a JSON string in the 'tags' field
    # and a simple string in the 'file' field
    response = client.post(
        "/upload",
        data={
            "file": "test.txt",
            "tags": '["abc", "def"]'
        }
    )
    assert response.status_code == 200
    assert response.json() == {"file": "test.txt", "tags": ["abc", "def"]}

